namespace error_message {
using char_t = char;
std::string TrimPath(const std::string &str);
#ifdef __GNUC__
int32_t FormatErrorMessage(char_t *str_dst, size_t dst_max, const char_t *format, ...)
    __attribute__((format(printf, 3, 4)));

